import{z as s,x as l,o as i,c as d,q as o,j as t,D as n,d as a,s as A,S as r,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"Hong–Stein 信息扩散","description":"","frontmatter":{"title":"Hong–Stein 信息扩散","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/hong-stein-diffusion.md","filePath":"econ/hong-stein-diffusion.md","lastUpdated":1791063341000}'),p={name:"econ/hong-stein-diffusion.md"};function D(m,E,f,F,h,S){const B=l("Mermaid");return i(),d("div",null,[E[2]||(E[2]=o('<h1 id="hong–stein-信息扩散" tabindex="-1">Hong–Stein 信息扩散 <a class="header-anchor" href="#hong–stein-信息扩散" aria-label="Permalink to &quot;Hong–Stein 信息扩散&quot;">​</a></h1><div class="epigraph"><p>新息先在一部分人那里，再慢慢传到另一部分人；观察价格的动量交易者把扩散变成先不足、后过度。</p><footer>—— Hong and Stein, A Unified Theory of Underreaction, Momentum Trading, and Overreaction in Asset Markets, Journal of Finance, 1999</footer></div><p><a href="/econ/dhs-overconfidence">上一课</a>靠私人信号精度。本课缺口是传播：即使每个人都贝叶斯，信息若在人群中分段到达，价格也会先反应不足；简单动量规则再把不足推成过度。不重写自我归因。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Hong 与 Stein（1999）设两类有限理性：消息观察者只看自己那一段基本面新息，不从价格提取别人的信息；动量交易者只看过去价格，用简单正反馈外推。新息在消息观察者之间逐渐扩散，价格初期反应不足，动量为正。动量交易者吃这个正的序列相关，把价格推过基本面，长期反转。缺口是第三条统一不足–动量–过度的路：有限注意力式的分割，而不是 BSV 体制或 DHS 精度。</p><p><span class="marginnote">Hong、Lim 与 Stein 后来用分析师覆盖检验：覆盖少的股票动量更强，符合「扩散慢」。那是经验，本课只要机制。</span></p><p><span class="marginnote">直觉类比：像一栋写字楼里逐层传开的内部消息——每层都以为自己先知道就够了，没人打电话问别的楼层。等消息一层层传完，股价才一步步涨完；专门盯着「最近涨了没有」的人再把这波趋势追过头。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>基本面新息分块，每块只被一群消息观察者看见。价格对未见块反应为零。动量交易者用滞后收益回归决定需求，寿命有限（又回到 DSSW 式的短视）。均衡路径：扩散期动量，过度期反转。比较静态：扩散越慢，动量窗口越长。</p>',9)),(i(),t(r,null,{default:n(()=>[A(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEWS%5B%22%E6%96%B0%E6%81%AF%E5%88%86%E6%AE%B5%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20UNDER%5B%22%E6%B6%88%E6%81%AF%E8%A7%82%E5%AF%9F%E8%80%85%E4%B8%8D%E8%AF%BB%E4%BB%B7%E6%A0%BC%3A%20%E5%8F%8D%E5%BA%94%E4%B8%8D%E8%B6%B3%22%5D%0A%20%20UNDER%20--%3E%20MOM%5B%22%E5%8A%A8%E9%87%8F%E4%BA%A4%E6%98%93%E8%80%85%E5%A4%96%E6%8E%A8%22%5D%0A%20%20MOM%20--%3E%20OVER%5B%22%E4%BB%B7%E6%A0%BC%E8%B6%8A%E8%BF%87%E5%9F%BA%E6%9C%AC%E9%9D%A2%2C%20%E5%8F%8D%E8%BD%AC%22%5D%0A"})]),fallback:n(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("机制是信息加总失败加正反馈。消息观察者的有限理性是：不从 \\(p\\) 反推别人的信号——这比「算错似然」更粗，接近"),e("a",{href:"/econ/bounded-rationality-satisficing"},"有限理性"),a("的程序限制。动量交易者不看基本面，只看价格的时间序列启发式。两类单独都不会走完不足–过度的全路径，合在一起会。套利者若又短视又资本有限，挡不住中间那段动量。")],-1)),E[5]||(E[5]=e("p",null,[a("与 "),e("a",{href:"/econ/emh"},"EMH"),a("：半强式假定公开信息立刻进价格。「公开但尚未传到所有人」是对信息集的社会学放松，不是对 Fama 分层的改写。")],-1)),E[6]||(E[6]=e("p",null,"消息观察者的程序限制是：不从 \\(p\\) 反演别人的块。若他们会读价格，扩散瞬间完成。动量交易者的程序是时间序列启发式，不看 \\(d\\)。有限寿命再次出现：他们吃中间的正相关，来不及为长期负相关负责——DSSW 式短视。分析师覆盖少则扩散慢，动量更强，是后文经验，本课只要这条比较静态。不写订单在簿上从一档传到另一档。",-1)),(i(),t(r,null,{default:n(()=>[A(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E6%96%B0%E6%81%AF%E5%88%86%E5%9D%97%EF%BC%9Ad1%2C%20d2%2C%20d3%22%5D%20--%3E%20GA%5B%22%E6%B6%88%E6%81%AF%E8%A7%82%E5%AF%9F%E8%80%85%E7%BE%A4%20A%20%E5%85%88%E7%9C%8B%E8%A7%81%E4%B8%80%E9%83%A8%E5%88%86%22%5D%0A%20%20B%20--%3E%20GB%5B%22%E7%BE%A4%20B%20%E7%A8%8D%E5%90%8E%E6%89%8D%E7%9C%8B%E8%A7%81%E5%8F%A6%E4%B8%80%E9%83%A8%E5%88%86%22%5D%0A%20%20GA%20--%3E%20NP%5B%22%E8%B0%81%E9%83%BD%E4%B8%8D%E8%AF%BB%E4%BB%B7%E6%A0%BC%EF%BC%9A%E4%B8%8D%E5%8F%8D%E6%8E%A8%E5%88%AB%E4%BA%BA%E5%B7%B2%E7%9F%A5%E5%A4%9A%E5%B0%91%22%5D%0A%20%20GB%20--%3E%20NP%0A%20%20NP%20--%3E%20PR%5B%22%E4%BB%B7%E6%A0%BC%E5%8F%AA%E9%9A%8F%E6%89%A9%E6%95%A3%E9%80%90%E6%AD%A5%E8%B5%B0%EF%BC%9A%E5%8F%8D%E5%BA%94%E4%B8%8D%E8%B6%B3%22%5D%0A%20%20PR%20--%3E%20MO%5B%22%E5%8A%A8%E9%87%8F%E4%BA%A4%E6%98%93%E8%80%85%E5%8F%AA%E8%AF%BB%E4%BB%B7%E6%A0%BC%EF%BC%9A%E5%A4%96%E6%8E%A8%E6%AD%A3%E6%94%B6%E7%9B%8A%22%5D%0A%20%20MO%20--%3E%20OV%5B%22%E4%B9%B0%E5%8E%8B%E6%8E%A8%E8%BF%87%E5%9F%BA%E6%9C%AC%E9%9D%A2%EF%BC%8C%E9%9A%8F%E5%90%8E%E5%8F%8D%E8%BD%AC%22%5D%0A"})]),fallback:n(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=o('<p><span class="marginnote">数字实例：新息总值 10 元，分三块先后传开。第一期只有 4 元到价，价格涨 4 元；动量交易者见涨追买，把还没传到的 6 元提前透支成 12 元的涨幅；三块传完、利好出尽，价格从 12 元回落——先不足、后过度的完整路径。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>若消息观察者能从价格充分提取，扩散瞬间完成，模型塌掉。动量交易者若会学习自己造成过度，正反馈减弱。本课不把所有动量写成 HS。也不写订单流在簿上的传播——那是微观结构。</p><p><span class="marginnote">常见误区：初学者容易以为 HS 里的交易者「算错了概率」。其实两类人都没有算错什么：消息观察者只是程序上不读价格，动量交易者只是程序上只读价格。出问题的是信息在人群中的流动方式，不是任何个人的贝叶斯运算。</span></p><p>后课默认：信念模型三件套（BSV/DHS/HS）之后，改评价函数的前景理论也可以定价，不必再错估 \\(p\\)。</p><p>新息分段到达，消息观察者不读价格，动量交易者只读价格：两类合在一起才走完不足–过度。</p><p>「公开但尚未传到所有人」放松的是信息集的到达，不是 Fama 分层本身。</p><p><span class="marginnote">动量交易者若学会自己造成过度，正反馈会减弱；本课不把所有动量写成 HS。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>信息分段扩散造成反应不足；动量交易者把它推成过度。</li><li>有限理性是程序：不读价格，或只读价格。</li><li>与 BSV/DHS 并列，不互相吞并。</li><li>扩散越慢，动量窗口越长。</li><li>若能从价格充分提取，模型塌掉。</li><li>出处：Hong and Stein, <em>JF</em> 1999。</li></ul>',10))])}const C=s(p,[["render",D]]);export{c as __pageData,C as default};
